style.css:
@-moz-document domain("youtube.com") {
/* ===========================
      BARRA MEHRAK
=========================== */

.ytp-play-progress{

    position:relative;
    overflow:visible!important;

    background:linear-gradient(
        90deg,
        #3fd99c 0%,
        #73ffd1 50%,
        #38c986 100%
    )!important;

    box-shadow:
        0 0 8px #49f1b1,
        0 0 18px rgba(73,241,177,.95),
        0 0 35px rgba(73,241,177,.75),
        0 0 70px rgba(73,241,177,.45);

    animation:
        mehrakPulse 1.8s ease-in-out infinite;
}


/* Aura */

.ytp-play-progress::before{

    content:"";

    position:absolute;

    inset:-5px;

    border-radius:999px;

    background:inherit;

    filter:blur(14px);

    opacity:.9;

    z-index:-1;

    animation:mehrakAura 2.2s ease-in-out infinite alternate;

}


/* Partículas falsas */

.ytp-play-progress::after{

    content:"";

    position:absolute;

    inset:-1px;

    pointer-events:none;

    background:

        radial-gradient(circle at 5% 50%, rgba(255,255,255,.95) 0 1px, transparent 2px),

        radial-gradient(circle at 20% 35%, rgba(133,255,214,.9) 0 2px, transparent 3px),

        radial-gradient(circle at 40% 70%, rgba(255,255,255,.8) 0 1px, transparent 2px),

        radial-gradient(circle at 62% 45%, rgba(108,255,203,.9) 0 2px, transparent 3px),

        radial-gradient(circle at 82% 55%, rgba(255,255,255,.95) 0 1px, transparent 2px),

        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.75),
            transparent
        );

    background-size:
        140px 100%,
        180px 100%,
        170px 100%,
        160px 100%,
        140px 100%,
        250% 100%;

    animation:
        mehrakParticles 4s linear infinite;

    mix-blend-mode:screen;

    opacity:.95;

}


/* ===========================
        KAVEH
=========================== */

.ytp-scrubber-button{

    width:72px!important;
    height:72px!important;

    margin-top:-33px!important;

    background:
        url("https://i.postimg.cc/505v3s0V/Kaveh-chibi-png.png")
        center center/contain
        no-repeat!important;

    background-color:transparent!important;

    border:none!important;

    border-radius:0!important;

    box-shadow:none!important;

    transition:
        transform .18s ease;

}


/* Hover */

.ytp-scrubber-button:hover{

    transform:
        scale(1.10)
        rotate(-2deg);

}


/* Remove bolinha */

.ytp-scrubber-button::before,
.ytp-scrubber-button::after{

    display:none!important;

}


/* ===========================
        ANIMAÇÕES
=========================== */

@keyframes mehrakPulse{

    0%{

        box-shadow:
            0 0 6px #49f1b1,
            0 0 18px rgba(73,241,177,.7),
            0 0 30px rgba(73,241,177,.45);

    }

    100%{

        box-shadow:
            0 0 12px #7dffe0,
            0 0 28px rgba(73,241,177,1),
            0 0 55px rgba(73,241,177,.85),
            0 0 90px rgba(73,241,177,.5);

    }

}

@keyframes mehrakAura{

    from{

        transform:scaleX(.99);

        opacity:.6;

    }

    to{

        transform:scaleX(1.01);

        opacity:1;

    }

}

@keyframes mehrakParticles{

    from{

        background-position:

            -150px 0,
            -200px 0,
            -180px 0,
            -170px 0,
            -140px 0,
            -250% 0;

    }

    to{

        background-position:

            400px 0,
            500px 0,
            450px 0,
            420px 0,
            390px 0,
            250% 0;

    }

}
}
